Summary:
[{
    "SDK_name": "AppLovin MAX SDK", 
    "API_name": "setHasUserConsent", 
    "conditions": [
        "Before using this API, the user's consent status should be determined whether they agree/disagree on interest-based advertising", 
        "This API can be utilized either via a custom mechanism or via third-party API.",
        "Consent values should be set before initializing the AppLovin SDK"
    ], 
    "effects": [
        "When the user's consent changes to allow or decline interest-based advertising, the user consent flag needs to be updated accordingly", 
        "Once this API is invoked with the user's consent status, AppLovin will respect the given value for the lifetime of the application or until the user changes their consent",
        "It enables the SDK to handle and pass along user's consent values on behalf of supported mediation partners"
    ], 
    "parameter_configuations": [
      {
	      "parameter_values":["true", "context"], 
	      "conditions":["The user consents to interest-based advertising"], 
	      "effects":["The user will receive interest-based advertisements"] 
      },
      {
	      "parameter_values":["false", "context"], 
	      "conditions":["The user does not consent to interest-based advertising"], 
	      "effects":["The user won't receive interest-based advertisements"] 
      }
    ]
  }]
